import{_ as t,o as i,c as a,a2 as o}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"Actions & Instant Preview","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/actions-and-preview.md","filePath":"user-guide/actions-and-preview.md","lastUpdated":1788085660000}'),n={name:"user-guide/actions-and-preview.md"};function r(s,e,l,d,c,h){return i(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="actions-instant-preview" tabindex="-1">Actions &amp; Instant Preview <a class="header-anchor" href="#actions-instant-preview" aria-label="Permalink to &quot;Actions &amp; Instant Preview&quot;">​</a></h1><p>Lertaro does more than find files at blazing speeds — it integrates a comprehensive context action system and a rich instant preview panel, letting you inspect, manage, and dispatch files without switching to File Explorer.</p><h2 id="_1-action-menu-deep-dive" tabindex="-1">1. Action Menu Deep Dive <a class="header-anchor" href="#_1-action-menu-deep-dive" aria-label="Permalink to &quot;1. Action Menu Deep Dive&quot;">​</a></h2><p>Press <code>Ctrl+O</code> or <code>→</code> on any search result (file, folder, application, or plugin entry) to expand the contextual action menu.</p><h3 id="built-in-core-actions-cheat-sheet" tabindex="-1">Built-in Core Actions Cheat Sheet <a class="header-anchor" href="#built-in-core-actions-cheat-sheet" aria-label="Permalink to &quot;Built-in Core Actions Cheat Sheet&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Action</th><th style="text-align:left;">Default Hotkey</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Open</strong></td><td style="text-align:left;"><code>Enter</code></td><td style="text-align:left;">Opens the selected item or launches the application with the system default program.</td></tr><tr><td style="text-align:left;"><strong>Reveal in Explorer</strong></td><td style="text-align:left;"><code>Ctrl+Enter</code></td><td style="text-align:left;">Opens the parent directory and highlights the item in Windows File Explorer.</td></tr><tr><td style="text-align:left;"><strong>Run as Administrator</strong></td><td style="text-align:left;"><code>Ctrl+Shift+Enter</code></td><td style="text-align:left;">Launches the selected application or script with elevated administrative permissions.</td></tr><tr><td style="text-align:left;"><strong>Copy Full Path</strong></td><td style="text-align:left;"><code>Ctrl+Shift+C</code></td><td style="text-align:left;">Copies the absolute path (e.g. <code>D:\\Projects\\app.exe</code>) to the clipboard.</td></tr><tr><td style="text-align:left;"><strong>Cut / Copy File</strong></td><td style="text-align:left;"><code>Ctrl+X</code> / <code>Ctrl+C</code></td><td style="text-align:left;">Places the file itself on the clipboard, ready to paste into Explorer or any folder.</td></tr><tr><td style="text-align:left;"><strong>Paste into Folder</strong></td><td style="text-align:left;"><code>Ctrl+V</code></td><td style="text-align:left;">When a folder is highlighted, pastes clipboard files directly into that directory.</td></tr><tr><td style="text-align:left;"><strong>Delete (Recycle Bin)</strong></td><td style="text-align:left;"><code>Delete</code></td><td style="text-align:left;">Safely moves the selected file or directory to the Windows Recycle Bin.</td></tr><tr><td style="text-align:left;"><strong>Permanent Delete</strong></td><td style="text-align:left;"><code>Shift+Delete</code></td><td style="text-align:left;">Permanently deletes the selected item (prompts for confirmation; cannot be recovered).</td></tr><tr><td style="text-align:left;"><strong>Windows Context Menu</strong></td><td style="text-align:left;">—</td><td style="text-align:left;">Expands the full native Windows Explorer context menu with third-party extensions and &quot;Send to&quot;.</td></tr></tbody></table><h3 id="action-menu-interaction-filtering" tabindex="-1">Action Menu Interaction &amp; Filtering <a class="header-anchor" href="#action-menu-interaction-filtering" aria-label="Permalink to &quot;Action Menu Interaction &amp; Filtering&quot;">​</a></h3><ul><li><strong>Type to Filter</strong>: Once the action menu opens, type immediately to filter actions by name (e.g., typing <code>copy</code> narrows the list to copy-related actions).</li><li><strong>Hierarchical Navigation</strong>: On items with submenus (such as &quot;Send to&quot;), press <code>→</code> or <code>Enter</code> to enter; press <code>←</code> or <code>Backspace</code> (when filter text is empty) to return to the parent level.</li><li><strong>Exit Menu</strong>: Press <code>Escape</code> to close the action menu and return to the main search result list.</li></ul><h2 id="_2-full-window-results-list-features" tabindex="-1">2. Full Window Results List Features <a class="header-anchor" href="#_2-full-window-results-list-features" aria-label="Permalink to &quot;2. Full Window Results List Features&quot;">​</a></h2><p>The Full Search Window (<code>Ctrl+F</code>) is designed for high-density file management and exploration:</p><ul><li><strong>Double-click Path Column</strong>: Double-clicking the <strong>Name</strong> column opens the file; double-clicking the <strong>Path</strong> column opens the containing parent folder directly.</li><li><strong>Infinite Streaming Results</strong>: When scanning millions of items, results stream into the view incrementally without waiting for the full index scan to conclude. You can interact with rows immediately as they arrive.</li><li><strong>Wrap-around Navigation</strong>: Pressing <code>↑</code> on the top row wraps around to the last item; pressing <code>↓</code> on the bottom row wraps back to the first.</li><li><strong>Window Dragging &amp; Size Memory</strong>: Drag the non-interactive top area of the window to reposition it; manually resized dimensions are automatically remembered across sessions.</li></ul><h2 id="_3-built-in-quicklook-instant-preview" tabindex="-1">3. Built-in QuickLook Instant Preview <a class="header-anchor" href="#_3-built-in-quicklook-instant-preview" aria-label="Permalink to &quot;3. Built-in QuickLook Instant Preview&quot;">​</a></h2><p>Press <code>Alt+P</code> on any result to summon the docked preview panel alongside the search window:</p><h3 id="supported-formats-rich-capabilities" tabindex="-1">Supported Formats &amp; Rich Capabilities <a class="header-anchor" href="#supported-formats-rich-capabilities" aria-label="Permalink to &quot;Supported Formats &amp; Rich Capabilities&quot;">​</a></h3><ul><li><strong>Images &amp; Vector Graphics</strong>: Crisp rendering and scaling for JPG, PNG, GIF (animated playback), BMP, WebP, ICO, SVG, and more.</li><li><strong>Documents &amp; Code Syntax</strong>: Highlighting and formatting for TXT, Markdown, JSON, XML, YAML, C#, Python, JS, HTML, etc.</li><li><strong>Audio &amp; Video Playback</strong>: Media files (MP4, MKV, AVI, MOV, WMV, MP3, WAV, FLAC, WMA) <strong>auto-play immediately</strong> with a theme-aware mini playback bar (play/pause, progress scrubbing, duration, mute). Playback stops instantly when switching items.</li><li><strong>Folder Structural Inspection</strong>: Shows up to 30 direct child items with file icons and sizes, automatically filtering system and hidden files.</li></ul><h3 id="adaptive-layout-pop-up-handling" tabindex="-1">Adaptive Layout &amp; Pop-up Handling <a class="header-anchor" href="#adaptive-layout-pop-up-handling" aria-label="Permalink to &quot;Adaptive Layout &amp; Pop-up Handling&quot;">​</a></h3><ul><li><strong>Adaptive Screen Bounds</strong>: Preview dimensions can be customized under <a href="./settings/general.html#preview"><strong>Settings → General → Preview</strong></a>; Lertaro guarantees the panel remains within the visible monitor bounds.</li><li><strong>Native Dialog Avoidance</strong>: When previewing password-protected Office documents, Lertaro temporarily hides both windows so the native password dialog can be interacted with, restoring seamlessly afterwards.</li><li><strong>Drag Source</strong>: The top area of the preview panel acts as a drag source — drag the previewed file directly into editors, browsers, or chat applications.</li></ul><h2 id="_4-plugin-interactive-rich-text-previews" tabindex="-1">4. Plugin Interactive &amp; Rich Text Previews <a class="header-anchor" href="#_4-plugin-interactive-rich-text-previews" aria-label="Permalink to &quot;4. Plugin Interactive &amp; Rich Text Previews&quot;">​</a></h2><p>QuickLook supports custom interactive preview cards provided by plugins:</p><ul><li><strong>Theme-Adaptive Rich Text</strong>: Rendered via modern WebView2 and native controls, automatically matching dark/light system themes with high-contrast typography and subtle translucent scrollbars.</li><li><strong>Interactive Plugin Cards</strong>: MDict dictionary lookups, live weather forecasts, instant webpage snapshots, and API debugging payloads.</li></ul><h2 id="_5-third-party-quicklook-bridge-optional" tabindex="-1">5. Third-party QuickLook Bridge (Optional) <a class="header-anchor" href="#_5-third-party-quicklook-bridge-optional" aria-label="Permalink to &quot;5. Third-party QuickLook Bridge (Optional)&quot;">​</a></h2><p>If you have installed the standalone open-source tool <strong>QuickLook</strong> (<a href="https://github.com/QL-Win/QuickLook" target="_blank" rel="noreferrer">QL-Win/QuickLook on GitHub</a>), enable the <strong>QuickLook Bridge</strong> plugin under <a href="./settings/plugins.html"><strong>Settings → Plugins</strong></a>.</p><ul><li><strong>External Preview Takeover</strong>: Connects via local named pipes to host external QuickLook preview windows anchored directly beside Lertaro.</li><li><strong>Seamless Fallback</strong>: If the external QuickLook process is not running, Lertaro smoothly falls back to its built-in preview engine.</li></ul><h2 id="_6-release-file-occupation" tabindex="-1">6. Release File Occupation <a class="header-anchor" href="#_6-release-file-occupation" aria-label="Permalink to &quot;6. Release File Occupation&quot;">​</a></h2><p>The official <strong>File Occupation Release</strong> plugin adds a single-selection action for existing files. It lists the processes currently using the file, including their PIDs and executable paths, and sends a request for those processes to release it. The action is disabled for folders, missing files, or multiple selections; the release button is also disabled when no process is detected. The themed dialog supports refresh and automatically hides itself from Alt+Tab while remaining above the search window.</p><h2 id="_7-add-to-favorites" tabindex="-1">7. Add to Favorites <a class="header-anchor" href="#_7-add-to-favorites" aria-label="Permalink to &quot;7. Add to Favorites&quot;">​</a></h2><p>CoreExtensions provides an <strong>Add to Favorites</strong> action for one existing file or folder. It opens a themed dialog for the display name and hides the action when the same path is already a favorite.</p>',27)])])}const g=t(n,[["render",r]]);export{u as __pageData,g as default};
